@router.patch('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def cambiar_serie(serie_id: int, datos: CambioSerie):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    clases = db.clases_de_serie(serie_id)
    base = next((c for c in clases if c['id'] == datos.desde_clase_id), None)
    if base is None:
        raise HTTPException(404, 'La clase no es de la serie')
    ahora = reloj.ahora()
    if db.a_fecha(base['inicio']) <= ahora:
        raise HTTPException(409, 'La clase ya empezó')
    alcanzadas = [c for c in clases if c['inicio'] >= base['inicio'] and c['estado'] != 'cancelada']
    cambios_clase = {c['id']: {} for c in alcanzadas}
    mails = []
    for c in alcanzadas:
        campos = cambios_clase[c['id']]
        if datos.hora is not None:
            local = db.a_fecha(c['inicio']).astimezone(reloj.MONTEVIDEO)
            nuevo = a_inicio(local.date(), datos.hora)
            if nuevo <= ahora:
                raise HTTPException(409, 'La nueva hora deja una clase en el pasado')
            if nuevo != db.a_fecha(c['inicio']):
                campos['inicio'] = db.a_texto(nuevo)
                mails.append((c, nuevo))
        if datos.cupo is not None:
            if db.confirmadas(c['id']) > datos.cupo:
                raise HTTPException(409, 'Hay clases con más reservas que el nuevo cupo')
            campos['cupo'] = datos.cupo
        if datos.instructor is not None:
            campos['instructor'] = datos.instructor
    cambios_serie = {k: getattr(datos, k) for k in ('hora', 'instructor', 'cupo') if getattr(datos, k) is not None}
    db.cambiar_serie(serie_id, cambios_serie, {k: v for k, v in cambios_clase.items() if v})
    for c, nuevo in mails:
        for s in db.socios_confirmados(c['id']):
            correo.enviar(s['email'], f"Cambio de horario: {c['nombre']} el {correo.fecha_y_hora(nuevo)}",
                          f"Hola {s['nombre']}, la clase {c['nombre']} pasó a {correo.fecha_y_hora(nuevo)}.")
    return ver_serie(db.serie(serie_id))


